struct Node* copyRandomList(struct Node*h){if(!h)return 0;for(struct Node*p=h;p;){struct Node*c=malloc(sizeof(*c));c->val=p->val;c->next=p->next;p->next=c;p=c->next;}for(struct Node*p=h;p;p=p->next->next)if(p->random)p->next->random=p->random->next;struct Node*r=h->next;for(struct Node*p=h;p;){struct Node*c=p->next;p->next=c->next;c->next=c->next?c->next->next:0;p=p->next;}return r;}
